BEGIN;
UPDATE public.grammar_exercises SET explanation_en = 'Tisch is a masculine noun, so its definite article is **der**: **der Tisch**. Die is for feminine nouns, das for neuter ones.' WHERE id = 'f2555a1b-d961-4a7f-b185-a621309d3649';
UPDATE public.grammar_exercises SET explanation_en = '**Frau** is feminine: **die Frau**.', explanation_de = 'Frau ist feminin: die Frau.' WHERE id = 'c68e4835-4ac3-4cc6-9372-3b67f4a09daf';
UPDATE public.grammar_exercises SET explanation_en = '**Mann** is masculine: **der Mann**.', explanation_de = 'Mann ist maskulin: der Mann.' WHERE id = 'fbc025da-31e9-44c1-9191-aab034a4e538';
UPDATE public.grammar_exercises SET explanation_en = 'In the plural every noun takes **die**, whatever its singular gender: der Stuhl → **die Stühle**.' WHERE id = 'e0ac0425-9aea-44f8-8354-7c41cfbcb0d3';
UPDATE public.grammar_exercises SET explanation_en = 'In the plural every noun takes **die**, even a neuter one: das Auto → **die Autos**.' WHERE id = 'be8069b8-e189-4fa9-9888-c78e2d51736f';
UPDATE public.grammar_exercises SET explanation_en = 'Auto (car) is a neuter noun, so the definite article is **das**: **das Auto**.' WHERE id = '88087bc2-73f6-5e32-a234-6674fcfff68e';
UPDATE public.grammar_exercises SET explanation_en = 'Computer is a masculine noun, so the definite article is **der**: **der Computer**.' WHERE id = '1beeb08a-c03e-5ab8-8969-b3aec12ef2e5';
UPDATE public.grammar_exercises SET explanation_en = 'Stuhl is masculine (der Stuhl). For something new or unknown, masculine takes **ein**: **ein Stuhl**. Eine is for feminine nouns only.' WHERE id = '1ce4f35f-6067-4fdf-a16b-689bb598fd67';
UPDATE public.grammar_exercises SET explanation_en = 'Schwester is feminine (die Schwester), so the indefinite article is **eine**: **eine Schwester**.' WHERE id = '404c4a60-3448-46bf-99ed-3405eda0bd0f';
UPDATE public.grammar_exercises SET explanation_en = 'Bild is neuter (das Bild). Neuter and masculine nouns both take **ein**: **ein Bild**.' WHERE id = '5d184615-c23d-44f3-96f4-275878ca8109';
UPDATE public.grammar_exercises SET explanation_en = 'Auto is neuter (das Auto), so it stays **ein**: **ein Auto**. Only masculine nouns change to einen after haben.', question_en = 'He has a car.' WHERE id = '51c0db3b-9a30-4ccb-8c6c-d1361eec51da';
UPDATE public.grammar_exercises SET explanation_en = 'Fenster is neuter (das Fenster). Neuter nouns take **ein**, like masculine ones: **ein Fenster**. Eine is feminine only.' WHERE id = '05649f0e-7308-50dd-8593-ac61018ef7e2';
UPDATE public.grammar_exercises SET explanation_en = 'Tasche is feminine (die Tasche), so the indefinite article is **eine**: **Ich habe eine Tasche.**' WHERE id = 'bb5c0422-921b-5e81-86fc-aa36c456ae8a';
UPDATE public.grammar_exercises SET explanation_en = 'After **sein**, a plain job normally takes no article: **Ich bin Lehrerin.** English says "a teacher"; German does not. With an adjective the article returns: **Ich bin eine gute Lehrerin.**', explanation_de = 'Nach ich bin steht ein Beruf meist ohne Artikel: Ich bin Lehrerin. Mit Adjektiv kommt der Artikel zurück: Ich bin eine gute Lehrerin.', question_en = 'How do you say the job? Write the sentence without the article: "Ich bin eine Lehrerin."', question_de = 'Wie sagt man den Beruf? Schreiben Sie den Satz ohne Artikel: „Ich bin eine Lehrerin.“' WHERE id = '1ed2c78f-8f65-52e3-9e63-97f2a5b0663b';
UPDATE public.grammar_exercises SET explanation_en = 'Computer is masculine (der Computer). After "Das ist" the masculine indefinite article is **ein**: **ein Computer**.' WHERE id = 'f12e69ee-d9c6-54f1-a2e7-b93304d4713c';
UPDATE public.grammar_exercises SET explanation_en = 'Female persons are feminine nouns, so Mutter takes **die**: **die Mutter**, like die Frau.' WHERE id = '319b95b6-ca95-5b56-b585-09aaaba51d9c';
UPDATE public.grammar_exercises SET explanation_en = 'Most alcoholic drinks are masculine: **der Wein**, der Sekt. But: **das Bier**.', explanation_de = 'Alkoholische Getränke sind meist maskulin: der Wein, der Sekt. Aber: das Bier.' WHERE id = 'f153c9f2-8ecc-586d-8b69-550edaf75dd1';
UPDATE public.grammar_exercises SET explanation_en = 'Mutter is feminine (die Mutter), so the pronoun is **sie**: **Sie ist meine Mutter.** The pronoun follows the article of the noun.' WHERE id = 'dd1c3d60-8ae7-4c94-8990-19633dcba36f';
UPDATE public.grammar_exercises SET explanation_en = '**Die Tasche** is feminine, so the pronoun is **sie**: die Tasche → sie.', explanation_de = 'Die Tasche ist feminin, deshalb steht das Pronomen sie: die Tasche → sie.' WHERE id = 'b19be5e4-48c0-5fad-a8a7-e16bf8e1772f';
UPDATE public.grammar_exercises SET explanation_en = 'The speaker talks about themselves with **ich**; the matching form of sein is **bin**: **Ich bin hier.**' WHERE id = '0ef58eff-0411-5dc0-9115-e607c9648f80';
UPDATE public.grammar_exercises SET explanation_en = 'For several people you address informally, the pronoun is **ihr**; the matching form of sein is **seid**: **Ihr seid meine Freunde.**' WHERE id = '4299d5ca-a80e-5528-a6b9-0ac7bee052bb';
UPDATE public.grammar_exercises SET explanation_en = 'The owner is ich, so the word is **mein** (my). Bruder is masculine (der Bruder), so there is no ending: **mein Bruder**.' WHERE id = 'd9887d31-0932-5143-b05e-3f903d659cd9';
UPDATE public.grammar_exercises SET explanation_en = 'The owner is er (he), so the word is **sein** (his). Auto is neuter (das Auto), so there is no ending: **Sein Auto**.' WHERE id = '46ae02ff-1593-5d9e-9956-bc9fb215b015';
UPDATE public.grammar_exercises SET explanation_en = 'The owner is sie (she), so the word is **ihr** (her). Tasche is feminine, and feminine nouns add **-e**: **ihre Tasche**.' WHERE id = '3bc06ffd-69f5-52b2-bb90-9c38dce7128b';
UPDATE public.grammar_exercises SET explanation_en = 'The owner is sie in the plural (they), so the word is **ihr** (their). Kinder is plural, and plurals add **-e**: **ihre Kinder**.' WHERE id = '210e89f8-2c89-5897-a247-a9bd3d84e4ae';
UPDATE public.grammar_exercises SET explanation_en = 'The owner is wir, so the word is **unser** (our). Land is neuter (das Land), so there is no ending: **unser Land**.' WHERE id = '3350c4ae-d08b-5a28-8e66-3cb273f39b5e';
UPDATE public.grammar_exercises SET explanation_en = 'The owner is du (informal you), so the word is **dein** (your). Schlüssel is masculine, so no ending: **dein Schlüssel**.' WHERE id = 'a85206a6-d5c3-5a86-8695-bfe661b1dd20';
UPDATE public.grammar_exercises SET explanation_en = 'The formal you (Sie) has the possessive **Ihr**, with a capital I. Adresse is feminine, so it adds **-e**: **Ihre Adresse**. Seine and eure belong to other owners.' WHERE id = 'b269d424-9f5f-5bfc-9703-50b0c0b5e5a4';
UPDATE public.grammar_exercises SET explanation_en = 'The owner is es (the child), and es uses **sein**, just like er. Buch is neuter, so there is no ending: **sein Buch**.' WHERE id = '41e1c650-118c-58a1-a6a9-ec54e540808c';
UPDATE public.grammar_exercises SET explanation_en = 'The owner is ich, so the word is **mein** (my). Vater is masculine (der Vater), so there is no ending: **Mein Vater**.' WHERE id = '9f8d70b7-2a9b-5c6c-8159-670b6cfd02c6';
UPDATE public.grammar_exercises SET explanation_en = 'The owner is ich, so the word is **mein**. Freundin is feminine (die Freundin), and feminine nouns add **-e**: **Meine Freundin**.' WHERE id = '388af6b1-9be8-5418-9d0f-1480baaa31b0';
UPDATE public.grammar_exercises SET explanation_en = 'Das comes first, the verb ist second, then the possessive and noun. Bruder is masculine, so mein has no ending: **Das ist mein Bruder.**' WHERE id = '5e65eab6-eba1-5797-beb8-e34750c5ceb1';
UPDATE public.grammar_exercises SET explanation_en = 'The owner is er, so **sein** (his). The ending follows the noun, not the owner: Schwester is feminine, so **-e**: **Das ist seine Schwester.**', question_de = '[das / ist / sein / Schwester] → Schreiben Sie den Satz.' WHERE id = '8908dc09-b16b-57e4-b056-e0f3060766c8';
UPDATE public.grammar_exercises SET explanation_en = 'The owner is wir, so **unser** (our). Auto is neuter (das Auto), so there is no ending: **Das ist unser Auto.**' WHERE id = 'd09ae745-12d0-5a21-9648-88fc36a55de1';
UPDATE public.grammar_exercises SET explanation_en = 'The formal you (Sie) has the possessive **Ihr**, always with a capital **I**. Adresse is feminine, so it adds **-e**: **Das ist Ihre Adresse.**' WHERE id = '83bab298-abc5-5e7f-a132-1bb60a689b8a';
UPDATE public.grammar_exercises SET explanation_en = 'The owner is sie in the plural (they), so the word is **ihr** (their). Vater is masculine, so there is no ending: **ihr Vater**.' WHERE id = '5ff6226a-1bd0-5e03-9643-7bb99ec7cccc';
UPDATE public.grammar_exercises SET explanation_en = 'After **ich** a regular verb takes the ending **-e**: wohn + e = **wohne**. Wohnst is the du-form, wohnt the er-form.' WHERE id = '25fe0c36-72d2-47f1-928f-b91d70481b29';
UPDATE public.grammar_exercises SET explanation_en = 'After **du** (informal you) a regular verb takes the ending **-st**: lern + st = **lernst**.', question_en = 'You are learning German. (lernen)' WHERE id = 'ea61494a-4f8e-4851-a5f6-1fa8a95364ab';
UPDATE public.grammar_exercises SET explanation_en = 'After **er** a regular verb takes the ending **-t**: spiel + t = **spielt**. Spielen without change is the wir/sie/Sie form.' WHERE id = '8f32fa13-901a-48f3-b07a-090b4bf980f4';
UPDATE public.grammar_exercises SET explanation_en = 'After **wir** a regular verb takes the ending **-en**, the same as the infinitive: **wir lernen**.' WHERE id = '602e3a32-2024-4fb8-8717-11ad8773aa78';
UPDATE public.grammar_exercises SET explanation_en = 'After **du** (informal you) a regular verb takes the ending **-st**: mach + st = **machst**. That also holds inside a question.' WHERE id = 'e7eb593b-0250-45d6-973c-d5b88fe2c7a4';
UPDATE public.grammar_exercises SET explanation_en = 'After **ihr** (informal you, plural) a regular verb takes the ending **-t**: spiel + t = **spielt** — the same form as er/sie/es.' WHERE id = '85084f27-567e-414e-9725-0b46aee3b6c4';
UPDATE public.grammar_exercises SET explanation_en = 'The stem heiß- already ends in an s-sound, so after **du** only **-t** is added: **du heißt**. Not "heißst".' WHERE id = '23cda354-67fa-4f71-8753-af3b48d540ed';
UPDATE public.grammar_exercises SET explanation_en = 'Take the stem (spielen without -en) and add the ich-ending **-e**: **spiele**. So: Ich spiele Fußball.' WHERE id = '02374938-9977-52c2-8828-2929e8075633';
UPDATE public.grammar_exercises SET explanation_en = 'Take the stem wohn- and add the du-ending **-st**: **wohnst**. So: Du wohnst in Berlin.' WHERE id = '5ae0746e-85ff-5cd9-a807-f3487450694c';
UPDATE public.grammar_exercises SET explanation_en = 'After **wir** the verb takes **-en**, which looks exactly like the infinitive: **wir hören**.' WHERE id = '877e964c-ed46-512b-ad1a-8b390a459e1d';
UPDATE public.grammar_exercises SET explanation_en = 'Sie meaning they (plural) takes the ending **-en**, identical to the infinitive: **sie arbeiten**.' WHERE id = 'd8082071-f2e5-5a17-84ff-c7335b4b14bc';
UPDATE public.grammar_exercises SET explanation_en = 'After **er** a regular verb takes the ending **-t**: lern + t = **lernt**. So: Er lernt Englisch.' WHERE id = '10822333-762f-5cf7-a878-3934135461a5';
UPDATE public.grammar_exercises SET explanation_en = 'After **ihr** (informal you, plural) the verb takes the ending **-t**: mach + t = **macht**. So: Was macht ihr?' WHERE id = '1981fa95-43a3-5ac5-87e5-0367f8b1e27f';
UPDATE public.grammar_exercises SET explanation_en = 'After **ich** the verb takes **-e**: arbeit + e = **arbeite**. The extra e is only needed before -st and -t (du arbeitest, er arbeitet).' WHERE id = '898a0861-f041-509c-84ba-57bf2f027afb';
UPDATE public.grammar_exercises SET explanation_en = 'After **ihr** (informal you, plural) the verb takes the ending **-t**: sag + t = **sagt**.' WHERE id = 'af4fc6ff-5616-5fb8-9ae3-6fa201d36fd3';
UPDATE public.grammar_exercises SET explanation_en = 'After **du** (informal you) the verb takes the ending **-st**: kauf + st = **kaufst**.' WHERE id = '62b2c518-9a21-5382-82e6-6efd80e34306';
UPDATE public.grammar_exercises SET explanation_en = 'After **ihr** the verb takes **-t**, but the stem arbeit- ends in -t, so an **e** is inserted: **arbeitet**. Not "arbeitt".' WHERE id = '4416ce85-3576-5677-9dea-08f332dbdd97';
UPDATE public.grammar_exercises SET explanation_en = 'After **er** the verb takes the ending **-t**: frag + t = **fragt**. So: Was fragt er?' WHERE id = '3d87b070-9689-58e0-9f0a-66393ce1b66a';
UPDATE public.grammar_exercises SET explanation_en = 'Aufstehen splits in a sentence: the verb part takes the ich-ending **-e** and stands second, the prefix auf stays at the end: **Ich stehe … auf.**' WHERE id = '9a58bc0a-594f-5a6f-b82c-146efa8d78c6';
UPDATE public.grammar_exercises SET explanation_en = 'Anrufen splits: the verb part takes the du-ending **-st** and stands second, the prefix an stays at the end: **Du rufst … an.**' WHERE id = 'bf805b90-6433-5303-95f3-96326a8783ef';
UPDATE public.grammar_exercises SET explanation_en = 'Einkaufen splits: the verb part takes the wir-ending **-en** and stands second, the prefix ein stays at the end: **Wir kaufen … ein.**' WHERE id = '50c103cc-d4e5-58d1-a75f-d3efa5ba5653';
UPDATE public.grammar_exercises SET explanation_en = 'Mitkommen splits: the verb part takes the er-ending **-t** and stands second, the prefix mit stays at the end: **Er kommt … mit.**' WHERE id = '1431d5ad-2d26-5430-9dbe-123d255c53b9';
UPDATE public.grammar_exercises SET explanation_en = 'Aufmachen splits: the verb part takes the ich-ending **-e** and stands second, the prefix auf stays at the end: **Ich mache … auf.**' WHERE id = '5c0728c9-3e01-5e60-85d0-3ef077c6d6af';
UPDATE public.grammar_exercises SET explanation_en = 'Zumachen splits: sie (she) takes the ending **-t** on the verb part, and the prefix zu stays at the end: **Sie macht … zu.**' WHERE id = '7f4e5108-b840-59d7-bd86-f4b855f04391';
UPDATE public.grammar_exercises SET explanation_en = 'Ankommen splits: der Zug is er, so the verb part takes **-t** and stands second, the prefix an stays at the end: **Der Zug kommt … an.**' WHERE id = '1173ceb0-6080-5b4d-af12-0c6783e3339c';
UPDATE public.grammar_exercises SET explanation_en = 'Ausgehen splits: after **wir** the verb part takes **-en** and stands second, the prefix aus stays at the end: **Wir gehen … aus.**' WHERE id = 'c5afdbe2-b275-5db5-8379-8c16b05b3393';
UPDATE public.grammar_exercises SET explanation_en = 'Abholen splits: after **ich** the verb part takes **-e** and stands second, the prefix ab stays at the end: **Ich hole … ab.**' WHERE id = '81ca8c57-dda8-56dc-9a74-39586ac3aa25';
UPDATE public.grammar_exercises SET explanation_en = 'Zuhören splits: after **er** the verb part takes **-t** and stands second, the prefix zu stays at the end: **Er hört … zu.**' WHERE id = 'ce39cf11-9cb2-5ecb-ada9-bc2dfe937c87';
UPDATE public.grammar_exercises SET explanation_en = 'Yes/no question: the verb (**stehst**) comes first, the prefix (**auf**) goes to the end.', explanation_de = 'Ja/Nein-Frage: Das Verb (stehst) steht vorn, die Vorsilbe (auf) am Ende.' WHERE id = '54801fe3-5b02-56dc-9c28-31bb6f620f04';
UPDATE public.grammar_exercises SET explanation_en = 'Yes/no question: the verb (**rufst**) comes first, the prefix (**an**) goes to the end.', explanation_de = 'Ja/Nein-Frage: Das Verb (rufst) steht vorn, die Vorsilbe (an) am Ende.' WHERE id = '9454a0c1-640f-54e9-81db-d63ea1557925';
UPDATE public.grammar_exercises SET explanation_en = 'Yes/no question: the verb (**kauft**) comes first, the prefix (**ein**) goes to the end.', explanation_de = 'Ja/Nein-Frage: Das Verb (kauft) steht vorn, die Vorsilbe (ein) am Ende.' WHERE id = '8a2be339-3196-5a98-a5e6-e41f4351e703';
UPDATE public.grammar_exercises SET explanation_en = 'Yes/no question: the verb (**kommt**) comes first, the prefix (**an**) goes to the end.', explanation_de = 'Ja/Nein-Frage: Das Verb (kommt) steht vorn, die Vorsilbe (an) am Ende.' WHERE id = 'fbe490d9-9b31-5e32-a6f3-dea1394f6863';
UPDATE public.grammar_exercises SET explanation_en = 'Abholen splits: hole stands second, and the prefix **ab** goes to the very end, after the time: **Ich hole dich um 8 Uhr ab.**' WHERE id = 'a31b05ff-9be9-5949-af9d-dcddeef307e2';
UPDATE public.grammar_exercises SET explanation_en = 'Zumachen splits: macht stands second, and the prefix **zu** goes to the very end: **Er macht die Tür zu.**' WHERE id = 'f1deffe2-8d4b-547c-8289-bdeafac5bc2c';
UPDATE public.grammar_exercises SET explanation_en = 'Einkaufen splits: kaufen stands second, and the prefix **ein** goes to the very end: **Wir kaufen heute ein.**' WHERE id = '0346934e-7e0a-59f8-a5c3-135fcf18a812';
UPDATE public.grammar_exercises SET explanation_en = 'Mitkommen splits: kommt stands second, and the prefix **mit** goes to the very end, after the time: **Ihr kommt um 8 Uhr mit.**' WHERE id = 'a375e841-56f8-5772-90d9-c5a079863bdd';
UPDATE public.grammar_exercises SET explanation_en = 'Aufstehen splits: **stehe** (ich-form) stands second, the prefix **auf** at the very end: **Ich stehe um 7 Uhr auf.** The time may also open the sentence.' WHERE id = '96b41b81-d57b-5bfe-91c8-93ef7d8982ca';
UPDATE public.grammar_exercises SET explanation_en = 'Einkaufen splits: **kaufen** (wir-form) stands second, the prefix **ein** at the very end: **Wir kaufen heute ein.** Heute may also open the sentence.' WHERE id = '1958acf0-ed11-583e-88e0-6a55fab00172';
UPDATE public.grammar_exercises SET explanation_en = 'Abholen splits: **holt** (er-form) stands second, the prefix **ab** at the very end: **Er holt dich um 8 Uhr ab.**' WHERE id = '51d74698-b413-58f3-bbc5-1fde9f41f83b';
UPDATE public.grammar_exercises SET explanation_en = 'Official (24-hour) time is hour + **Uhr** + minutes: 14:30 = **vierzehn Uhr dreißig**.', explanation_de = 'Offizielle Zeit: Stunde + Uhr + Minuten: 14:30 = vierzehn Uhr dreißig.' WHERE id = '2e4e344c-3116-5304-9f6e-afbed5d037e9';
UPDATE public.grammar_exercises SET explanation_en = 'In everyday German, halb names the NEXT hour: **halb drei** = 2:30 (half way to three), not 3:30.' WHERE id = '36f2bd1a-d22a-5c9e-9f7e-a197b992f696';
UPDATE public.grammar_exercises SET explanation_en = 'For a quarter past, everyday German uses Viertel nach + the CURRENT hour: 2:15 = **Viertel nach zwei**.' WHERE id = '69162961-90a8-5f76-9cad-865fb2c8b9fb';
UPDATE public.grammar_exercises SET explanation_en = 'For a quarter to, everyday German uses Viertel vor + the NEXT hour: 2:45 = **Viertel vor drei**.' WHERE id = 'f12532bf-6089-544f-83ef-8bfcc2940f6b';
UPDATE public.grammar_exercises SET explanation_en = 'Official time always includes the word **Uhr**, even on the full hour: 8:00 = **acht Uhr**.', acceptable_answers = '["acht Uhr"]'::jsonb WHERE id = '2d34c5aa-a512-50b5-a1c5-57dd04acb619';
UPDATE public.grammar_exercises SET explanation_en = 'Parts of the day take **am**: **am Abend**, am Morgen, am Nachmittag. One exception: **in der Nacht**. Clock times take **um**: um 8 Uhr.', explanation_de = 'am + Tageszeit: am Morgen, am Abend (aber: in der Nacht).' WHERE id = '8970aaea-186c-58b0-bcf2-fdc7bbc3a632';
UPDATE public.grammar_exercises SET explanation_en = 'In everyday German, halb names the NEXT hour: 5:30 = **halb sechs** (half way to six). "Halb fünf" would be 4:30; "fünf Uhr dreißig" is the official form.' WHERE id = 'a8759f56-1064-5599-99bc-5bea3f752bfb';
UPDATE public.grammar_exercises SET explanation_en = 'The weekdays in order: Montag, Dienstag, Mittwoch, **Donnerstag**, Freitag, Samstag, Sonntag. After Mittwoch comes **Donnerstag**.' WHERE id = 'c307bcfa-5945-5c82-a3b8-5b2c30d48a39';
UPDATE public.grammar_exercises SET explanation_en = 'Everyday German uses the 12-hour clock and counts minutes past the hour with nach: 18:20 = **zwanzig nach sechs**.', acceptable_answers = '["zwanzig nach sechs","zwanzig nach 6","zehn vor halb sieben"]'::jsonb WHERE id = '827c155d-7b87-53a3-b047-d53ab532f296';
UPDATE public.grammar_exercises SET explanation_en = 'Official time uses the 24-hour clock with the word Uhr, so midnight is **null Uhr** (zero o''clock).' WHERE id = 'ffb96fdf-5140-582a-bc5a-b3d17e131ea3';
UPDATE public.grammar_exercises SET explanation_en = 'Shortly before the full hour, count to the next hour with **vor**: 2:50 = **zehn vor drei**.', explanation_de = 'Kurz vor der vollen Stunde zählt man mit vor zur nächsten Stunde: 2:50 = zehn vor drei.' WHERE id = '3e14842d-3e34-5d86-9284-5954e9593b61';
UPDATE public.grammar_exercises SET explanation_en = 'Haben is irregular; after **ich** the form is **habe**: **Ich habe ein Auto.** Hast is for du, hat for er/sie/es.', question_en = 'I have a car.' WHERE id = '68be03d3-c547-41dc-9dc0-772fa974f74f';
UPDATE public.grammar_exercises SET explanation_en = 'After **er** the form of haben is **hat**: **Er hat Hunger.** German "has" hunger rather than "is" hungry.', question_en = 'He is hungry.' WHERE id = 'cb35f9d0-86d8-4f7c-b41d-3e6c1e2e1e4c';
UPDATE public.grammar_exercises SET explanation_en = 'After **du** (informal you) the form of haben is **hast**: **Hast du Zeit?** In a yes/no question the verb comes first.' WHERE id = 'ff343b73-534f-42bc-bc58-1fb8c6fbb1c5';
UPDATE public.grammar_exercises SET explanation_en = 'Sie meaning she (singular) takes **hat**, the same form as er and es: **Sie hat Zeit.** Haben would be for sie meaning they.' WHERE id = '3286c2b6-0c89-5187-ae66-841a73bcc4c4';
UPDATE public.grammar_exercises SET explanation_en = 'The formal you (Sie) takes **haben**, and in a yes/no question the verb comes first: **Haben Sie Zeit?**' WHERE id = 'e8388d41-3d49-59c8-ac5b-020c596c2649';
UPDATE public.grammar_exercises SET explanation_en = 'After **du** (informal you) the form of haben is **hast**, and it opens the yes/no question: **Hast du einen Bruder?**' WHERE id = '7b8f0fd0-cce3-51e8-8430-4a4ecb5c47c3';
UPDATE public.grammar_exercises SET explanation_en = 'Sein is irregular; after **ich** the form is **bin**: **Ich bin müde.** Bist is for du, ist for er/sie/es.' WHERE id = 'dcfdd24d-b6da-4222-92a9-2e816bf4cc5d';
UPDATE public.grammar_exercises SET explanation_en = 'After **er** the form of sein is **ist**: **Er ist Lehrer.** Note: no article before the job.' WHERE id = '34957c67-c29b-43c9-b3ef-5346fa68fa52';
UPDATE public.grammar_exercises SET explanation_en = 'After **wir** the form of sein is **sind**: **Wir sind in Berlin.** Seid belongs to ihr.' WHERE id = '9fd52b13-6cb9-4430-b0b7-52d4a63c0a63';
UPDATE public.grammar_exercises SET explanation_en = 'After **du** (informal you) the form of sein is **bist**; in a yes/no question the verb comes first: **Bist du Student?**' WHERE id = '0fe8146d-6e90-4c1c-b127-618c44e456ba';
UPDATE public.grammar_exercises SET explanation_en = 'Sie meaning they (plural) takes **sind**, the same form as wir: **Sie sind Kollegen.** Ist would be for sie meaning she.' WHERE id = '1e3a7370-9e9c-55ea-b513-496b45421861';
UPDATE public.grammar_exercises SET explanation_en = 'Here das points to one thing (Kaffee), so sein takes **ist**, like er/sie/es: **Das ist Kaffee.** For a plural noun it is **Das sind …**: Das sind Kollegen.', explanation_de = 'Das steht mit ist, wenn es um eine Sache geht: Das ist Kaffee. Mit einem Nomen im Plural: Das sind …' WHERE id = '19f1aa27-7634-5599-8a61-8f69e259f6d4';
UPDATE public.grammar_exercises SET explanation_en = 'Sie meaning she (singular) takes **ist**, like er and das: **Sie ist meine Schwester.** Sind would be for sie meaning they.' WHERE id = '459b2960-6610-57b4-b4f9-631bf6eeed01';
UPDATE public.grammar_exercises SET explanation_en = 'Statement: Du bist müde. In a yes/no question the verb moves to position 1: **Bist du müde?** Bist is the du-form of sein.' WHERE id = '5c5c272b-ff81-5811-83b6-6e7fde71ba1b';
UPDATE public.grammar_exercises SET explanation_en = 'Statement: Du hast Zeit. In a yes/no question the verb moves to position 1: **Hast du Zeit?** Hast is the du-form of haben.' WHERE id = 'd1777221-6b65-55c3-8ecd-dbaa0583db0c';
UPDATE public.grammar_exercises SET explanation_en = 'Statement: Du kommst aus Polen. In a yes/no question the verb moves to position 1: **Kommst du aus Polen?** The du-ending -st stays.' WHERE id = '426d0034-6957-500d-84d9-4c2844e5338c';
UPDATE public.grammar_exercises SET explanation_en = 'The stem arbeit- ends in -t, so the du-form adds an extra e: **arbeitest**. In a yes/no question it comes first: **Arbeitest du viel?**' WHERE id = '8c1f7c82-1210-5d1b-8f48-8ad60f3cfa78';
UPDATE public.grammar_exercises SET explanation_en = 'The formal you (Sie) uses the verb form **wohnen** (same as the infinitive). In a yes/no question it comes first: **Wohnen Sie in Berlin?**' WHERE id = '14eac77e-603e-51e0-9a53-4e18fa5b9d8f';
UPDATE public.grammar_exercises SET explanation_en = 'The formal you (Sie) uses the form **sprechen** (same as the infinitive), placed first in a yes/no question: **Sprechen Sie Englisch?**' WHERE id = 'e327c296-1ea8-51db-b3c5-a6409f00534c';
UPDATE public.grammar_exercises SET explanation_en = 'Statement: Du trinkst gern Kaffee. In a yes/no question the verb moves to position 1: **Trinkst du gern Kaffee?**' WHERE id = 'd58cff5b-760c-57bc-b030-05d1201f8846';
UPDATE public.grammar_exercises SET explanation_en = 'Statement: Du kochst gern. In a yes/no question the verb moves to position 1: **Kochst du gern?** The du-ending -st stays.' WHERE id = 'a3ddac97-a8fb-5ddc-8a2d-3c7763e89667';
UPDATE public.grammar_exercises SET explanation_en = 'Say **Ja** and repeat the statement in the ich-form: **Ja, ich komme aus Italien.** "Ja, komme." has no subject; "ich kommst" has the wrong verb ending, and "du kommst" answers about the other person, not about you.', explanation_de = 'Ja + die Aussage in der ich-Form: Ja, ich komme aus Italien.', question_en = 'Answer yes and repeat the statement: Kommst du aus Italien?', options = '["Ja, ich komme aus Italien.","Ja, komme.","Ja, ich kommst aus Italien.","Ja, du kommst aus Italien."]'::jsonb WHERE id = 'ffec1d33-2826-5332-93e5-2b8efe7ece89';
UPDATE public.grammar_exercises SET explanation_en = 'In a yes/no question the verb comes first and the subject second. Bist is the du-form of sein: **Bist du müde?**' WHERE id = '0b5c7d74-0e60-51b3-802e-50a4c8457f36';
UPDATE public.grammar_exercises SET explanation_en = 'In a yes/no question the verb comes first, then the subject. After du the ending is -st: **Wohnst du in Köln?**' WHERE id = 'e52a4dca-4065-58a0-ae8f-de107844d5f2';
UPDATE public.grammar_exercises SET explanation_en = 'In a yes/no question the verb comes first, then the subject. After du the ending is -st: **Kommst du aus Polen?**' WHERE id = '20edbc50-95ff-5914-9381-9673b2716b68';
UPDATE public.grammar_exercises SET explanation_en = 'Mitkommen splits: in the yes/no question **kommst** comes first, du second, and the prefix **mit** goes to the very end: **Kommst du am Samstag mit?**' WHERE id = 'fa2176d8-3252-57b7-8e4e-0c009303f306';
UPDATE public.grammar_exercises SET explanation_en = 'In a polite yes/no question the verb comes first and the formal you (Sie) second. Sie uses the form wohnen: **Wohnen Sie in Berlin?**' WHERE id = '78abfd45-9be5-51ff-a294-12c1aa43d6e9';
UPDATE public.grammar_exercises SET explanation_en = 'In a polite yes/no question the verb comes first and the formal you (Sie) second. Sie uses the form haben: **Haben Sie Kinder?**' WHERE id = '6f0fbd89-79de-53ab-9b82-67b4f5f734ed';
UPDATE public.grammar_exercises SET explanation_en = 'A yes/no question starts with the verb: **Wohnst du in Köln?** The other three start with a question word (Wie, Wo, Wer) and ask for information.' WHERE id = '81cb7d4e-9f92-5d7a-a8a9-ac0a5302565e';
COMMIT;
